import random, sys, itertools, json
sys.path.insert(0,'/workspace/submission')
import main as M

def atom_ok(op, pat, w):
    if op=='match': return list(w)==list(pat)
    if op=='startswith': return list(w[:len(pat)])==list(pat)
    if op=='endswith': return list(w[len(w)-len(pat):])==list(pat) if len(w)>=len(pat) else False
    if op=='contains':
        p=list(pat); ww=list(w)
        if len(p)==0: return True
        for i in range(len(ww)-len(p)+1):
            if ww[i:i+len(p)]==p: return True
        return False

def ev(e,w):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op in ('match','startswith','endswith','contains'): return atom_ok(op,e['path'],w)
    if op=='not': return not ev(e['arg'],w)
    if op=='and': return all(ev(a,w) for a in e['args'])
    if op=='or': return any(ev(a,w) for a in e['args'])

def brute_accept(req,w):
    # tokens indices -> map to tokens
    services=req['services']; wt=[services[i] for i in w]
    allow=any(ev(r['when'],wt) for r in req['rules'] if r['action']=='allow')
    drop=any(ev(r['when'],wt) for r in req['rules'] if r['action']=='drop')
    return allow and not drop

def rand_expr(tokens, depth, atompool):
    choices=['true','false','match','startswith','endswith','contains','not','and','or']
    if depth<=0:
        choices=['true','false','match','startswith','endswith','contains']
    op=random.choice(choices)
    if op in ('true','false'): return {'op':op}
    if op in ('match','startswith','endswith','contains'):
        p=[random.choice(tokens) for _ in range(random.randint(0,3))] if tokens else []
        atompool.append((op,tuple(p)))
        return {'op':op,'path':p}
    if op=='not': return {'op':'not','arg':rand_expr(tokens,depth-1,atompool)}
    args=[rand_expr(tokens,depth-1,atompool) for _ in range(random.randint(0,3))]
    return {'op':op,'args':args}

